import heapq


def kth_largest(nums: list[int], k: int) -> int:
    """Find the kth largest element in an unsorted list.

    Uses a min-heap of size k for O(n log k) time and O(k) space.
    """
    if not nums or k < 1 or k > len(nums):
        raise ValueError(f"k={k} is out of bounds for list of length {len(nums)}")
    return heapq.nlargest(k, nums)[-1]


def kth_largest_sort(nums: list[int], k: int) -> int:
    """Find the kth largest element using sorting. O(n log n) time."""
    if not nums or k < 1 or k > len(nums):
        raise ValueError(f"k={k} is out of bounds for list of length {len(nums)}")
    return sorted(nums, reverse=True)[k - 1]


# ---------- tests ----------

def test_basic():
    assert kth_largest([3, 2, 1, 5, 6, 4], 2) == 5
    assert kth_largest_sort([3, 2, 1, 5, 6, 4], 2) == 5


def test_k_equals_one():
    assert kth_largest([3, 2, 1], 1) == 3


def test_k_equals_len():
    assert kth_largest([3, 2, 1], 3) == 1


def test_duplicates():
    assert kth_largest([3, 3, 3, 3], 2) == 3


def test_negative_numbers():
    assert kth_largest([-1, -2, -3, -4], 2) == -2


def test_single_element():
    assert kth_largest([42], 1) == 42


def test_invalid_k():
    import pytest
    with pytest.raises(ValueError):
        kth_largest([1, 2, 3], 0)
    with pytest.raises(ValueError):
        kth_largest([1, 2, 3], 4)


def test_empty_list():
    import pytest
    with pytest.raises(ValueError):
        kth_largest([], 1)


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])

